import React from 'react';
import { CTableTransfer } from '@cloud-materials/common';
import type { FetcherOptions, FetcherResponse } from '@cloud-materials/common/es/CTable/core';
import type { TableConfig } from '@cloud-materials/common/es/CTable';

const dataSource = new Array(15).fill(null).map((_, index) => ({
  value: `${index + 1}`,
  label: `Option ${index + 1}`,
  name: `Name ${index + 1}`,
}));

const onFetchDataSource = ({ currentPage, pageSize, filterValues }: FetcherOptions<any>) => {
  const { search: { name = '', property = '' } = {} } = filterValues || {};
  const data = dataSource.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  return new Promise<FetcherResponse>(resolve => {
    setTimeout(() => {
      resolve({
        data: name
          ? data.filter(item => item.name.toLocaleLowerCase().replace(/\s+/g, '').indexOf(name) !== -1)
          : property
          ? data.filter(item => item.value.toLocaleLowerCase().indexOf(property) !== -1)
          : data,
        total: 20,
      });
    }, 1000);
  });
};

