import React from 'react';
import { CTable, CTableTransfer } from '@cloud-materials/common';
import type { FetcherOptions, FetcherResponse } from '@cloud-materials/common/es/CTable/core';

interface DataType {
  basic: {
    info: {
      value: string;
      label: string;
    };
  };
}
export const dataSource = new Array(20).fill(null).map((_, index) => ({
  basic: {
    info: {
      value: `${index + 1}`,
      label: `Option ${index + 1}`,
    },
  },
}));
export const onFetchDataSource = ({ currentPage, pageSize }: FetcherOptions<any>) => {
  return new Promise<FetcherResponse>(resolve => {
    setTimeout(() => {
      resolve({
        data: dataSource.slice((currentPage - 1) * pageSize, currentPage * pageSize),
        total: 20,
      });
    }, 1000);
  });
};

export default () => {
  const config = CTable.defineConfig<DataType>({
    rowKey: rowData => {
      return rowData.basic.info.value;
    },
    pagination: true,
    columns: [
      {
        title: '名称',
        dataIndex: 'basic.info.label',
      },
      {
        title: '值',
        dataIndex: 'basic.info.value',
      },
    ],
  });
  return (
    <CTableTransfer
      defaultSelectedValues={['1', '2']}
      CTableProps={[{ ...config, fetcher: onFetchDataSource }, { ...config }]}
      onChange={(keys, data) => {
        console.log('%c [ data ]-54', 'font-size:13px; background:pink; color:#bf2c9f;', data);
        console.log('keys', keys);
      }}
    />
  );
};
